-- Kalo · el café con leche estaba cruzado con café negro (USDA «coffee, brewed»): 2 kcal. Ahora mitad café colado y mitad leche entera, sin azúcar.
update public.alimentos set por_100g = '{"azucar_g":2.525,"b12_ug":0.225,"b1_mg":0.03,"b2_mg":0.125,"b3_mg":0.14,"b6_mg":0.02,"calcio_mg":57.5,"carbos_g":2.4,"cobre_mg":0.015,"colesterol_mg":5,"fibra_g":0,"folato_ug":3.5,"fosforo_mg":43.5,"grasa_g":1.635,"grasa_sat_g":0.935,"hierro_mg":0.02,"kcal":31,"magnesio_mg":6.5,"manganeso_mg":0.01,"potasio_mg":90.5,"proteina_g":1.635,"selenio_ug":1.85,"sodio_mg":22.5,"vit_a_ug":23,"vit_c_mg":0,"vit_d_ug":0.65,"vit_e_mg":0.04,"vit_k_ug":0.2,"zinc_mg":0.195}'::jsonb, fuente = 'Receta Kalo: ½ café colado (USDA 171890) + ½ leche entera (USDA), sin azúcar', porcion_base = '{"texto":"1 taza","gramos":240}'::jsonb, porciones = '[{"texto":"1 taza","gramos":240},{"texto":"1 vaso","gramos":250},{"texto":"1 pocillo","gramos":180},{"texto":"100 g","gramos":100}]'::jsonb where id = 'cafe-con-leche';
-- La opción «Almojábana con café con leche» le sumaba leche aparte por el error: queda 1 almojábana + 1 taza de café con leche
delete from public.opcion_items where opcion_id = (select id from public.opciones where nombre = 'Almojábana con café con leche' and fuente = 'kalo') and alimento_id = 'leche-entera';
update public.opcion_items set cantidad = 1 where opcion_id = (select id from public.opciones where nombre = 'Almojábana con café con leche' and fuente = 'kalo') and alimento_id = 'cafe-con-leche';
